choose.when:
SELECT EXISTS(SELECT 1 FROM order_return_check
        WHERE id=#{sourceId} AND rental_order_id=#{orderId}
        AND check_status IN ('no_issue','auto_closed','admin_closed') AND claim_created=0 AND closed_at IS NOT NULL)

SELECT EXISTS(SELECT 1 FROM admin_case_action WHERE id=#{sourceId}
        AND action_type='resolve_order_issue' AND target_type='rental_order' AND target_id=#{orderId}
        AND operator_confirmed_at IS NOT NULL AND action_status='executing')

