mapper.sql:
WHERE 1=1
AND r.refund_status=#{query.status}
AND r.biz_order_type=#{query.businessType}
AND EXISTS( SELECT 1 FROM payment_channel_suborder s WHERE s.id=r.payment_channel_suborder_id AND s.factory_id=#{query.factoryId})

mapper.select:
